--   child key   : Question Code
--   feeders     : 4 -- one per (view, DECLARED ANCHOR EXPRESSION)
--   payload     : 3 attribute(s), NULL-PADDED TO THE SATELLITE
--
--   The child key is the MODEL'S declared key, read from data_7.js
--   sats[].childkey keyed by sats[].code. target.key_name is the HUB key
--   name and is null on all 1,888 satellite rows, so it is never read here.
--
--   The hashdiff is GUARDED against an all-null input: without the guard
--   every all-null row hashes to ONE value and the population collapses.

with feeders as (select * from (
    select
        md5(upper(HUB_PROPOSAL_BK__K0)) as HUB_PROPOSAL_HK,
        'OTHERS_SPECIFY' as QUESTION_CODE,
        null::varchar as QUESTION_TEXT,
        IF_OTHERS_PLEASE_SPECIFY as RESPONSE_VALUE,
        'MAXI_HLTH_UWR_VW_DATA_BASIC_DETAIL_ATTRIBUTE_MULTISET_ATTRIBUTE_ATTRIBUTES_PIVOT_VW' as RECORD_SOURCE,
        current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_uwr_bd_attr_msa_pv') }}
    where HUB_PROPOSAL_K0__EMIT
    union all
    select
        md5(upper(HUB_PROPOSAL_BK__K0)) as HUB_PROPOSAL_HK,
        'OTHERS_SPECIFY' as QUESTION_CODE,
        QUESTION_TEXT as QUESTION_TEXT,
        MEDIUS_ANSWER as RESPONSE_VALUE,
        'MAXI_HLTH_UWR_VW_DATA_MEMBERS_MEMBER_DETAILS_MULTISET_ATTRIBUTE_ATTRIBUTES_PIVOT_VW' as RECORD_SOURCE,
        current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_uwr_mem_memd_msa_pv') }}
    where HUB_PROPOSAL_K0__EMIT
    union all
    select
        md5(upper(HUB_PROPOSAL_BK__K0)) as HUB_PROPOSAL_HK,
        'MEDIUS_QUESTIONS' as QUESTION_CODE,
        null::varchar as QUESTION_TEXT,
        MEDIUSQUESTIONS as RESPONSE_VALUE,
        'MAXI_HLTH_UWR_VW_DATA_MEMBERS_MEMBER_DETAILS_PIVOT_VW' as RECORD_SOURCE,
        current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_uwr_mem_memd_pv') }}
    where HUB_PROPOSAL_K0__EMIT
    union all
    select
        md5(upper(HUB_PROPOSAL_BK__K0)) as HUB_PROPOSAL_HK,
        null::varchar as QUESTION_CODE,
        NAME as QUESTION_TEXT,
        VALUE as RESPONSE_VALUE,
        'MAXI_HLTH_UWR_VW_DATA_MEMBERS_QUESTIONNAIRE' as RECORD_SOURCE,
        current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_uwr_mem_qnr') }}
    where HUB_PROPOSAL_K0__EMIT
)), hashed as (select *,
        case when QUESTION_TEXT is not null or RESPONSE_VALUE is not null
             then md5(upper(coalesce(QUESTION_TEXT::varchar,'') || '||' || coalesce(RESPONSE_VALUE::varchar,'')))
        end as SAT_PROPOSAL_QUESTIONNAIRE_HASHDIFF
    from feeders)

select * from hashed
where HUB_PROPOSAL_HK is not null
  and SAT_PROPOSAL_QUESTIONNAIRE_HASHDIFF is not null
  and QUESTION_CODE is not null
